import{_ as o,o as a,c as r,a2 as i}from"./chunks/framework.D9QjdNhv.js";const p=JSON.parse('{"title":"Diretrizes de Segurança Turbo","description":"","frontmatter":{},"headers":[],"relativePath":"guia/seguranca-turbo.md","filePath":"guia/seguranca-turbo.md","lastUpdated":null}'),t={name:"guia/seguranca-turbo.md"};function s(c,e,d,n,l,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="diretrizes-de-seguranca-turbo" tabindex="-1">Diretrizes de Segurança Turbo <a class="header-anchor" href="#diretrizes-de-seguranca-turbo" aria-label="Permalink to &quot;Diretrizes de Segurança Turbo&quot;">​</a></h1><p>Para operar em desenvolvimento contínuo e acelerado (<strong>Modo Turbo</strong>) sem risco de perda de dados ou regressões técnicas, o projeto estabelece regras mandatórias de engenharia.</p><h2 id="principios-norteadores" tabindex="-1">Princípios Norteadores <a class="header-anchor" href="#principios-norteadores" aria-label="Permalink to &quot;Princípios Norteadores&quot;">​</a></h2><h3 id="_1-politica-de-backup-obrigatorio-pre-mutacao" tabindex="-1">1. Política de Backup Obrigatório Pré-Mutação <a class="header-anchor" href="#_1-politica-de-backup-obrigatorio-pre-mutacao" aria-label="Permalink to &quot;1. Política de Backup Obrigatório Pré-Mutação&quot;">​</a></h3><p>Nenhum arquivo físico de usuário (em especial <code>CONTROLE PAGAMENTOS.xlsx</code>) pode ser alterado sem a criação prévia de uma cópia snapshot na pasta <code>.backups/</code>:</p><ul><li>Formato do arquivo de backup: <code>.backups/CONTROLE_PAGAMENTOS_{timestamp}.xlsx</code></li><li>O diretório <code>.backups/</code> é ignorado no controle de versão (<code>.gitignore</code>).</li></ul><h3 id="_2-zero-arquivos-temporarios-em-disco" tabindex="-1">2. Zero Arquivos Temporários em Disco <a class="header-anchor" href="#_2-zero-arquivos-temporarios-em-disco" aria-label="Permalink to &quot;2. Zero Arquivos Temporários em Disco&quot;">​</a></h3><ul><li>A geração de documentos PDF (QuestPDF) e compactação ZIP opera estritamente em <strong>memória RAM</strong> (<code>MemoryStream</code> / <code>byte[]</code>).</li><li>Testes automatizados que necessitem de arquivos SQLite ou Excel utilizam caminhos temporários do sistema operacional (<code>Path.GetTempPath()</code>) e removem os artefatos no bloco <code>finally</code>.</li></ul><h3 id="_3-concorrencia-segura-e-anti-bloqueio" tabindex="-1">3. Concorrência Segura e Anti-Bloqueio <a class="header-anchor" href="#_3-concorrencia-segura-e-anti-bloqueio" aria-label="Permalink to &quot;3. Concorrência Segura e Anti-Bloqueio&quot;">​</a></h3><ul><li>O acesso a arquivos de planilhas utiliza o modo <code>FileShare.ReadWrite</code>.</li><li>Em caso de contenção por outro processo (por exemplo, arquivo aberto no Microsoft Excel ou LibreOffice pelo usuário), o motor aciona <strong>5 tentativas com jitter exponencial</strong> antes de falhar.</li></ul><h3 id="_4-portoes-de-validacao-estritos-gates" tabindex="-1">4. Portões de Validação Estritos (Gates) <a class="header-anchor" href="#_4-portoes-de-validacao-estritos-gates" aria-label="Permalink to &quot;4. Portões de Validação Estritos (Gates)&quot;">​</a></h3><p>Cada fase do projeto deve cumprir simultaneamente:</p><ul><li><strong>0 erros de compilação</strong> (<code>dotnet build</code> com saída exit code 0).</li><li><strong>0 avisos impeditivos</strong> (warnings tratados proativamente).</li><li><strong>100% de testes aprovados</strong> (<code>dotnet test</code> e <code>npm run build</code> passando com sucesso).</li><li><strong>Commits Atômicos</strong>: Cada entrega funcional é commitada e enviada para o repositório remoto com mensagem semântica clara.</li></ul>',13)])])}const g=o(t,[["render",s]]);export{p as __pageData,g as default};
